namespace LucianoPereira\Crucible\Reporting\Document\Blocks;

use LucianoPereira\Crucible\Reporting\Document\Block;

use function base64_decode;

/**
 * A JPEG image — the raw file bytes, embedded verbatim (DCTDecode,
 * no re-encoding). Placed at content width unless $width narrows it;
 * height always follows the JPEG's own aspect ratio.
 */
final readonly class Image implements Block
{
    /**
     * A 4x3 solid-red baseline JPEG (693 bytes, 3 channels, no Adobe
     * APP14 marker) — the same tiny fixture used across this project's
     * own image/SVG tests, real enough that `getimagesizefromstring()`
     * reports genuine width/height/channels.
     */
    private const string SAMPLE_JPEG = '';

    public function __construct(
        public string $jpegBytes,
        public ?float $width = null,
    ) {}

    public static function sample(): self
    {
        return new self((string) base64_decode(self::SAMPLE_JPEG, true));
    }
}
